def _decorate_ticks(self, ax, name, ticklabels, start_edge, end_edge):
    ax.set_xlim((start_edge, end_edge))

    # Ensure tick positions match the expected tick counts
    if len(ticklabels) != len(self.tick_pos):
        raise ValueError("Number of tick labels must match number of tick positions.")

    # Set tick positions. Use self.xticks if provided, else default with tick_pos.
    if hasattr(self, 'xticks') and self.xticks is not None:
        ax.set_xticks(self.xticks)
    else:
        ax.set_xticks(self.tick_pos)

    ax.set_xticklabels(ticklabels)

    # Set xlabel only if name is specified and use_index is true
    if name is not None and self.use_index:
        ax.set_xlabel(name)
